function soon(t){if(typeof toast==="function")toast(t);else alert(t)}
function mat(title){return (S.mats||[]).find(m=>m.t===title)}
function realTiles(id,kind){const st=MAN.styles[id],its=st[kind]||[],pc=dev==="pc",base=MAN.base+id+"/";
 const links=it=>{const f=it.files,L=[];
  if(kind==="png"||kind==="tx")L.push(["PNG",f.png]);
  else if(kind==="bg")L.push(["9:16",f.v],["16:9",f.h]);
  else if(kind==="an")L.push(pc?["MOV",f.mov]:["MP4",f.capcut]);
  else if(kind==="tr")L.push(pc?["9:16",f.mov_v]:["9:16",f.capcut_v],pc?["16:9",f.mov_h]:["16:9",f.capcut_h]);
  else if(kind==="ov")L.push(["9:16",pc&&f.mov_v?f.mov_v:f.black_v],["16:9",pc&&f.mov_h?f.mov_h:f.black_h]);
  return L.filter(x=>x[1]).map(x=>`<a href="${e(x[1])}" target="_blank" rel="noopener">${x[0]} ↓</a>`).join("")};
 const vid=k=>k==="an"||k==="tr"||k==="ov";
 return `<div class="pk-real">${its.map(it=>`<div class="pk-ri ${kind}">${vid(kind)?`<video src="${e(base+it.prev)}#t=0.1" muted loop playsinline autoplay preload="metadata"></video>`:`<img src="${e(base+it.prev)}" loading="lazy" alt="">`}<b>${e(it.name)}</b>${kind==="ov"&&it.screen?`<small>режим «Экран»</small>`:""}<span class="dl">${links(it)}</span></div>`).join("")}</div>`}
function musicView(id){return `<div class="pk-list">${(MUSIC[id]||[]).map(m=>`<a class="pk-row" href="https://pixabay.com/music/search/${encodeURIComponent(m)}/" target="_blank" rel="noopener"><span class="ic">♪</span><span class="tx"><b>${e(m)}</b><small>Pixabay Music · бесплатно, можно в коммерцию</small></span><span class="arr">↗</span></a>`).join("")}</div><p class="pk-note">Ищи по настроению, слушай 10–15 секунд и бери трек, у которого темп совпадает с темпом монтажа. Для рекламы клиента — Artlist или Epidemic Sound.</p>`}
function card(s){return `<article class="pk-svc"><div class="hd"><b>${e(s.n)}${s.pick?'<span class="pk-pick">ВЫБОР БУШИ</span>':""}</b><span class="pk-plats">${s.p.map(x=>`<span class="pk-plat">${e(x)}</span>`).join("")}</span></div>
 <p class="what">${e(s.w)}</p>
 <div class="pk-tiers"><div class="f"><i>Бесплатно</i>${e(s.fr)}</div><div class="p"><i>Подписка</i>${e(s.pd)}${s.unsure?'<br><span style="color:var(--muted)">цену уточни на сайте — она зависит от страны</span>':""}</div></div>
 <p class="pk-tip"><em>Когда брать:</em> ${e(s.tip)}</p>
 <a class="pk-btn ghost" style="justify-self:start;font-size:13px;padding:8px 12px" href="${e(s.u)}" target="_blank" rel="noopener">Открыть сайт ↗</a></article>`}

